const MAP_MAKER_ASSETS: readonly MapMakerAsset[] = JSON.parse(MAP_MAKER_ASSET_DATA_JSON) as MapMakerAsset[];

const assetsById = new Map<string, MapMakerAsset>();
for (const asset of MAP_MAKER_ASSETS) {
  if (assetsById.has(asset.id)) {
    throw new Error(`Duplicate map-maker asset id: "${asset.id}"`);
  }
  assetsById.set(asset.id, asset);
}

export function getMapMakerAssets(): readonly MapMakerAsset[] {
  return MAP_MAKER_ASSETS;
}

export function getMapMakerAsset(id: string): MapMakerAsset {
  if (typeof id !== 'string' || id.trim().length === 0) {
    throw new TypeError(`Map-maker asset id must be a non-empty string; received ${String(id)}`);
  }
  const canonicalId = id === 'as0' ? MAP_MAKER_ASSET_ID_ALIASES.as0 : id;
  const asset = assetsById.get(canonicalId);
  if (!asset) {
    throw new RangeError(`Unknown map-maker asset id: "${id}" (resolved as "${canonicalId}")`);
  }
  return asset;
}

export function getMapMakerAssetSrc(id: string, usage: MapMakerAssetUsage): string {
  if (usage !== 'tile' && usage !== 'element' && usage !== 'preview') {
    throw new RangeError(`Unknown map-maker asset source usage: "${String(usage)}"`);
  }
  const asset = getMapMakerAsset(id);
  if (usage === 'element') {
    return asset.src;
  }
  if (usage === 'tile') {
    return asset.tileSrc ?? asset.src;
  }
  return asset.previewSrc ?? asset.tileSrc ?? asset.src;
}
